function stateLayer(name,base,target){
 const b=im([path.join(S,base),'-alpha','off','-depth','8','rgb:-']),t=im([path.join(W,target),'-resize','1672x941!','-alpha','off','-depth','8','rgb:-']);
 const a=Buffer.alloc(1672*941*4);let error=0;
 for(let i=0;i<1672*941;i++){let v=0;for(let c=0;c<3;c++){const B=b[3*i+c]/255,T=t[3*i+c]/255;v=Math.max(v,T>=B?(T-B)/Math.max(1-B,1e-8):(B-T)/Math.max(B,1e-8));}let av=Math.min(255,Math.ceil(v*255));v=av/255;a[4*i+3]=av;for(let c=0;c<3;c++){a[4*i+c]=v?Math.max(0,Math.min(255,Math.round((t[3*i+c]-(1-v)*b[3*i+c])/v))):0;error=Math.max(error,Math.abs(Math.round(a[4*i+c]*v+b[3*i+c]*(1-v))-t[3*i+c]));}}
 save(path.join(O,name),im(['-size','1672x941','-depth','8','rgba:-','PNG32:-'],a));records.push({name,base,height:941,method:'full_scene_state_straight_alpha',max_reconstruction_error_8bit:error});
}
